/** Keep normal odds until 5 endless minutes, then linearly reach all elites at 10. */
export function eliteChanceFormula(endlessSeconds = null) {
  if (endlessSeconds === null) return eliteChance;
  const s = endlessEliteSettings;
  const progress = Math.max(0, Math.min(1,
    (endlessSeconds - s.rampStartSeconds) / Math.max(1, s.rampEndSeconds - s.rampStartSeconds)));
  return Math.max(0, Math.min(1, eliteChance + (s.targetChance - eliteChance) * progress));
}

export const mobBaseHp = 60;
export const shirokoBossStats = { hpMultiplier: 100, contactDamage: 15 };
// New Mob spawns scale with survival time; linear by default, continuing after 15 minutes.
export const mobHealthScaling = { targetSeconds: 15 * 60, targetHp: 350, exponent: 1 };
// Timer text size and gap in pixels below the top EXP bar.
export const survivalTimerSettings = { fontScale: 1.25, offsetBelowExp: 8 };

/** Basic Mob HP: 60 + (350-60) * (survivalSeconds/900)^1, rounded. */
export function basicMobHpFormula(seconds) {
  const progress = Math.max(0, seconds) / mobHealthScaling.targetSeconds;
  return Math.max(1, Math.round(mobBaseHp + (mobHealthScaling.targetHp - mobBaseHp) *
    progress ** mobHealthScaling.exponent));
}

