// Yuuka rolls on each regular enemy arrival, not on boss spawn attempts.
export const yuukaSpawnSettings = { baseChance: 0.0025, unlockKills: 100, cooldownKills: 100,
  pityStart: 500, pityStepKills: 50, pityStepChance: 0.005, maxChance: 0.025 };

/** Chance after unlock/cooldown: .25%, plus .5 percentage points per pity step, capped at 2.5%. */
export function yuukaSpawnChanceFormula(kills, hasSpawned = false, bossActive = false) {
  const settings = yuukaSpawnSettings;
  if (kills < settings.unlockKills || (hasSpawned && kills < settings.cooldownKills)) return 0;
  const steps = Math.floor(Math.max(0, kills - settings.pityStart) / settings.pityStepKills);
  return Math.min(settings.maxChance, settings.baseChance + steps * settings.pityStepChance) *
    (bossActive ? specialEnemySettings.bossSpawnMultiplier : 1);
}

