// Enemy damage scales with current player level and active survival minutes.
export const enemyDamageScaling = { base: 1, levelDivisor: 6, minutesDivisor: 4 };

/** floor(enemyBase * variantMultiplier * (1 + (level/6) * (minutes/4))). */
export function enemyContactDamageFormula(baseDamage, level, survivalSeconds, variantMultiplier = 1) {
  const s = enemyDamageScaling;
  const minutes = Math.max(0, survivalSeconds) / 60;
  const scale = s.base + (Math.max(1, level) / s.levelDivisor) * (minutes / s.minutesDivisor);
  return Math.max(0, Math.floor(baseDamage * variantMultiplier * scale));
}

