/** Nearest integer with ties to even, used by the EXP curve. */
export function roundToEven(value) {
  const lower = Math.floor(value), fraction = value - lower;
  return fraction === 0.5 ? lower + (lower % 2) : Math.round(value);
}
export function levelExpFormula(level) {
  const current = Math.max(1, Math.floor(level));
  return current === 1 ? 79 : roundToEven((4 * (current + 1)) ** 2.1) - roundToEven((4 * current) ** 2.1);
}

/** Standard Mob report: round(3 + playerLevel / (2 + reportTier)). */
export function mobExpFormula(level, tier) {
  return Math.round(reportSettings.mobBase + Math.max(1, Math.floor(level)) /
    (reportSettings.mobDivisor + Math.max(0, Math.min(3, Math.floor(tier)))));
}

/** Yuuka spawn HP: round((normal player damage + 100) / 100 * 900). */
export const yuukaHpSettings = { offset: 100, divisor: 100, base: 900 };
export function yuukaHpFormula(damage) {
  return Math.max(1, Math.round((Math.max(0, damage) + yuukaHpSettings.offset) /
    yuukaHpSettings.divisor * yuukaHpSettings.base));
}

/** ATK/SPD/PICKUP/Haste percent bonus multiplier (25% -> 1.25). */
export function percentBonusFormula(percent) {
  return 1 + Math.max(0, Number.isFinite(Number(percent)) ? Number(percent) : 0) / 100;
}

